/* i18n.js */
(() => {
  'use strict';

  const supported = ['en', 'uk', 'ru', 'be', 'kk'];
  const names = { en: 'English', uk: 'Українська', ru: 'Русский', be: 'Беларуская', kk: 'Қазақша' };
  const flags = { en: 'flag--en', uk: 'flag--uk', ru: 'flag--ru', be: 'flag--be', kk: 'flag--kk' };
  const translations = window.CHILLOS_TRANSLATIONS || {};

  const storage = {
    get(key) { try { return window.localStorage.getItem(key); } catch (_) { return null; } },
    set(key, value) { try { window.localStorage.setItem(key, value); } catch (_) {} },
    remove(key) { try { window.localStorage.removeItem(key); } catch (_) {} }
  };
  const session = {
    get(key) { try { return window.sessionStorage.getItem(key); } catch (_) { return null; } },
    set(key, value) { try { window.sessionStorage.setItem(key, value); } catch (_) {} }
  };

  const saved = storage.get('chillos.locale');
  let current = supported.includes(saved) ? saved : 'en';

  function getValue(key, locale = current) {
    return translations[locale]?.[key] ?? translations.en?.[key] ?? key;
  }

  function updateMetadata() {
    const page = document.body?.dataset.page || 'index';
    const title = getValue(`page.${page}.title`);
    const description = getValue(`page.${page}.description`);
    if (title && !title.startsWith('page.')) document.title = title;
    const meta = document.querySelector('meta[name="description"]');
    if (meta && description && !description.startsWith('page.')) meta.content = description;
  }

  function updatePicker() {
    document.querySelectorAll('[data-current-language]').forEach((element) => {
      element.textContent = names[current];
    });
    document.querySelectorAll('[data-current-flag]').forEach((element) => {
      element.className = `language-flag ${flags[current]}`;
    });
    document.querySelectorAll('[data-locale]').forEach((button) => {
      const active = button.dataset.locale === current;
      button.classList.toggle('active', active);
      if (button.getAttribute('role') === 'option') button.setAttribute('aria-selected', String(active));
    });
  }

  function apply(root = document) {
    root.querySelectorAll('[data-i18n]').forEach((element) => {
      element.textContent = getValue(element.dataset.i18n);
    });
    root.querySelectorAll('[data-i18n-html]').forEach((element) => {
      element.innerHTML = getValue(element.dataset.i18nHtml);
    });
    root.querySelectorAll('[data-i18n-placeholder]').forEach((element) => {
      element.setAttribute('placeholder', getValue(element.dataset.i18nPlaceholder));
    });
    root.querySelectorAll('[data-i18n-title]').forEach((element) => {
      element.setAttribute('title', getValue(element.dataset.i18nTitle));
    });
    root.querySelectorAll('[data-i18n-aria-label]').forEach((element) => {
      element.setAttribute('aria-label', getValue(element.dataset.i18nAriaLabel));
    });
    document.documentElement.lang = current;
    document.documentElement.dataset.locale = current;
    updateMetadata();
    updatePicker();
  }

  function setLocale(locale, options = {}) {
    if (!supported.includes(locale)) locale = 'en';
    current = locale;
    if (options.persist !== false) storage.set('chillos.locale', current);
    apply();
    if (options.emit !== false) {
      document.dispatchEvent(new CustomEvent('chillos:localechange', { detail: { locale: current, persisted: options.persist !== false } }));
    }
  }

  function closePicker(picker) {
    const menu = picker?.querySelector('.language-picker__menu');
    const button = picker?.querySelector('.language-picker__button');
    if (menu) {
      menu.classList.remove('is-open');
      menu.hidden = true;
    }
    button?.setAttribute('aria-expanded', 'false');
  }

  function closeAllPickers(except = null) {
    document.querySelectorAll('[data-language-picker]').forEach((picker) => {
      if (picker !== except) closePicker(picker);
    });
  }

  function openPicker(picker) {
    const menu = picker?.querySelector('.language-picker__menu');
    const button = picker?.querySelector('.language-picker__button');
    if (!menu || !button) return;
    closeAllPickers(picker);
    menu.hidden = false;
    menu.classList.add('is-open');
    button.setAttribute('aria-expanded', 'true');
  }

  function bindPickers() {
    document.querySelectorAll('[data-language-picker]').forEach((picker) => {
      if (picker.dataset.bound === '1') return;
      picker.dataset.bound = '1';
      const button = picker.querySelector('.language-picker__button');
      const menu = picker.querySelector('.language-picker__menu');
      if (!button || !menu) return;
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const isOpen = button.getAttribute('aria-expanded') === 'true';
        if (isOpen) closePicker(picker); else openPicker(picker);
      });
      menu.addEventListener('click', (event) => {
        event.stopPropagation();
        const target = event.target instanceof Element ? event.target : null;
        const localeButton = target?.closest('[data-locale]');
        if (!localeButton) return;
        setLocale(localeButton.dataset.locale);
        closeAllPickers();
      });
    });
  }

  document.addEventListener('click', (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const localeButton = target?.closest('[data-locale]');
    if (localeButton) {
      setLocale(localeButton.dataset.locale);
      closeAllPickers();
      const modal = document.getElementById('belarusLanguageModal');
      if (modal) {
        modal.hidden = true;
        document.body.classList.remove('modal-open');
        session.set('chillos.byLanguageChosen', '1');
      }
      return;
    }
    if (!target?.closest('[data-language-picker]')) closeAllPickers();
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeAllPickers();
  });

  window.ChillI18n = {
    apply,
    get: getValue,
    get locale() { return current; },
    hasSavedLocale() { return supported.includes(storage.get('chillos.locale')); },
    clearSavedLocale() { storage.remove('chillos.locale'); },
    setLocale,
    supported,
    names
  };

  bindPickers();
  apply();
})();
/* geo.js */
(() => {
  'use strict';

  const params = new URLSearchParams(location.search);
  if (params.get('resetLocale') === '1') window.ChillI18n?.clearSavedLocale();
  if (params.has('lang')) window.ChillI18n?.setLocale(params.get('lang'));

  const CACHE_KEY = 'chillos.geo.v3';
  const CACHE_TTL = 30 * 60 * 1000;
  const GEO_CLASSES = ['geo-ua', 'geo-ru', 'geo-kz', 'geo-by', 'geo-default'];
  const AUTO_LOCALE = { UA: 'uk', RU: 'ru', KZ: 'kk' };
  let lastCheckAt = 0;
  let activeRequest = null;
  let testCountry = null;

  const storage = {
    get(key) { try { return window.localStorage.getItem(key); } catch (_) { return null; } },
    set(key, value) { try { window.localStorage.setItem(key, value); } catch (_) {} }
  };
  const session = {
    get(key) { try { return window.sessionStorage.getItem(key); } catch (_) { return null; } }
  };

  function cachedCountry() {
    try {
      const value = JSON.parse(storage.get(CACHE_KEY) || 'null');
      if (value && /^[A-Z]{2}$/.test(value.country) && Date.now() - value.savedAt < CACHE_TTL) return value.country;
    } catch (_) {}
    return null;
  }

  function saveCountry(country) {
    if (!/^[A-Z]{2}$/.test(country || '')) return;
    storage.set(CACHE_KEY, JSON.stringify({ country, savedAt: Date.now() }));
  }

  async function requestJson(url, parser, timeout = 4200) {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { cache: 'no-store', credentials: 'omit', signal: controller.signal });
      if (!response.ok) throw new Error(String(response.status));
      return parser(await response.json());
    } finally {
      window.clearTimeout(timer);
    }
  }

  async function requestText(url, parser, timeout = 4200) {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { cache: 'no-store', credentials: 'omit', signal: controller.signal });
      if (!response.ok) throw new Error(String(response.status));
      return parser(await response.text());
    } finally {
      window.clearTimeout(timer);
    }
  }

  async function detectCountry({ ignoreOverride = false } = {}) {
    const override = params.get('geo')?.toUpperCase();
    if (!ignoreOverride && override && /^[A-Z]{2}$/.test(override)) return override;
    if (testCountry) return testCountry === 'DEFAULT' ? null : testCountry;

    const providers = [
      () => requestJson('https://api.country.is/', (data) => data.country),
      () => requestText('https://ipapi.co/country/', (text) => text.trim()),
      () => requestJson('https://ipwho.is/', (data) => data.success === false ? null : data.country_code)
    ];

    for (const provider of providers) {
      try {
        const country = String(await provider() || '').trim().toUpperCase();
        if (/^[A-Z]{2}$/.test(country)) {
          saveCountry(country);
          return country;
        }
      } catch (_) {}
    }

    return cachedCountry();
  }

  function setStatus(key) {
    const status = document.getElementById('geoStatus');
    if (!status) return;
    status.dataset.i18n = key;
    status.textContent = window.ChillI18n?.get(key) || key;
  }

  function prepareStatusButton() {
    const status = document.getElementById('geoStatus');
    if (!status || status.dataset.geoBound === '1') return;
    status.dataset.geoBound = '1';
    status.tabIndex = 0;
    status.setAttribute('role', 'button');
    status.dataset.i18nTitle = 'geo.refresh';
    status.setAttribute('title', window.ChillI18n?.get('geo.refresh') || 'Recheck region');
    const activate = (event) => {
      if (event.type === 'keydown' && !['Enter', ' '].includes(event.key)) return;
      event.preventDefault();
      refresh({ force: true });
    };
    status.addEventListener('click', activate);
    status.addEventListener('keydown', activate);
  }

  function setTabletUkraine(enabled) {
    const tablet = document.getElementById('geoTablet');
    if (!tablet) return;
    const keys = enabled
      ? ['demo.ua.label', 'demo.ua.title', 'demo.ua.text']
      : ['demo.tabletLabel', 'demo.tabletTitle', 'demo.tabletText'];
    [tablet.querySelector('.tablet-label'), tablet.querySelector('strong'), tablet.querySelector('small')]
      .forEach((element, index) => { if (element) element.dataset.i18n = keys[index]; });
    window.ChillI18n?.apply(tablet);
  }

  function showBelarusChoice() {
    if (window.ChillI18n?.hasSavedLocale() || session.get('chillos.byLanguageChosen')) return;
    const modal = document.getElementById('belarusLanguageModal');
    if (!modal) return;
    modal.hidden = false;
    document.body.classList.add('modal-open');
    window.ChillI18n?.apply(modal);
  }

  function applyCountry(country, options = {}) {
    const resolved = country || 'DEFAULT';
    document.body.classList.remove(...GEO_CLASSES);
    document.body.classList.add(`geo-${resolved.toLowerCase()}`);
    document.body.dataset.country = country || '';
    document.documentElement.dataset.country = country || '';

    const warning = document.getElementById('ruAccessWarning');
    const support = document.getElementById('uaSupportWidget');
    const donateCode = document.getElementById('uaDonateCode');
    const secretFlag = document.getElementById('kzSecretFlag');
    const kerchief = document.getElementById('kzKerchief');

    [warning, support, donateCode, secretFlag, kerchief].forEach((element) => { if (element) element.hidden = true; });
    setTabletUkraine(false);

    const shouldAutoLocalize = options.forceLocale || !window.ChillI18n?.hasSavedLocale();
    if (country === 'UA') {
      if (shouldAutoLocalize) window.ChillI18n?.setLocale(AUTO_LOCALE.UA, { persist: false });
      if (support && !session.get('chillos.uaSupportDismissed')) support.hidden = false;
      if (donateCode) donateCode.hidden = false;
      setTabletUkraine(true);
      setStatus('geo.status.UA');
    } else if (country === 'RU') {
      if (shouldAutoLocalize) window.ChillI18n?.setLocale(AUTO_LOCALE.RU, { persist: false });
      if (warning && !session.get('chillos.ruWarningDismissed')) warning.hidden = false;
      setStatus('geo.status.RU');
    } else if (country === 'KZ') {
      if (shouldAutoLocalize) window.ChillI18n?.setLocale(AUTO_LOCALE.KZ, { persist: false });
      if (secretFlag) secretFlag.hidden = false;
      if (kerchief) kerchief.hidden = false;
      setStatus('geo.status.KZ');
    } else if (country === 'BY') {
      setStatus('geo.status.BY');
      window.setTimeout(showBelarusChoice, 120);
    } else {
      setStatus(country ? 'geo.status.DEFAULT' : 'geo.status.ERROR');
    }

    document.dispatchEvent(new CustomEvent('chillos:geoready', { detail: { country, test: Boolean(options.test) } }));
  }

  async function refresh({ force = false, ignoreOverride = false } = {}) {
    if (document.body.dataset.page === '404') return null;
    const now = Date.now();
    if (!force && now - lastCheckAt < 10000) return document.body.dataset.country || null;
    if (activeRequest) return activeRequest;
    lastCheckAt = now;
    setStatus('geo.detecting');
    activeRequest = detectCountry({ ignoreOverride })
      .then((country) => {
        applyCountry(country);
        return country;
      })
      .catch(() => {
        const fallback = cachedCountry();
        applyCountry(fallback);
        return fallback;
      })
      .finally(() => { activeRequest = null; });
    return activeRequest;
  }

  function buildTestPanel() {
    if (params.get('geotest') !== '1' || document.getElementById('geoTestPanel')) return;
    const panel = document.createElement('aside');
    panel.id = 'geoTestPanel';
    panel.className = 'geo-test-panel';
    panel.innerHTML = `
      <div class="geo-test-panel__head"><strong data-i18n="geo.test.title">Region test</strong><button type="button" data-geo-test-close aria-label="Close">×</button></div>
      <p data-i18n="geo.test.hint">Changes affect only this tab. After enabling or disabling a VPN, press Auto.</p>
      <div class="geo-test-panel__buttons">
        <button type="button" data-geo-test="AUTO" data-i18n="geo.test.auto">Detect automatically</button>
        <button type="button" data-geo-test="UA">UA</button><button type="button" data-geo-test="RU">RU</button>
        <button type="button" data-geo-test="KZ">KZ</button><button type="button" data-geo-test="BY">BY</button>
        <button type="button" data-geo-test="DEFAULT" data-i18n="geo.test.standard">Standard mode</button>
      </div>`;
    document.body.append(panel);
    window.ChillI18n?.apply(panel);
    panel.addEventListener('click', (event) => {
      const target = event.target instanceof Element ? event.target : null;
      if (target?.closest('[data-geo-test-close]')) {
        panel.remove();
        return;
      }
      const button = target?.closest('[data-geo-test]');
      if (!button) return;
      const value = button.dataset.geoTest;
      panel.querySelectorAll('[data-geo-test]').forEach((item) => item.classList.toggle('active', item === button));
      if (value === 'AUTO') {
        testCountry = null;
        refresh({ force: true, ignoreOverride: true });
      } else {
        testCountry = value;
        applyCountry(value === 'DEFAULT' ? null : value, { forceLocale: true, test: true });
      }
    });
  }

  function start() {
    prepareStatusButton();
    buildTestPanel();
    refresh({ force: true });
  }

  if (document.body.dataset.page === '404') {
    applyCountry(null);
  } else if ('requestIdleCallback' in window) {
    requestIdleCallback(start, { timeout: 500 });
  } else {
    window.setTimeout(start, 80);
  }

  window.addEventListener('focus', () => refresh());
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') refresh();
  });

  document.addEventListener('chillos:localechange', () => {
    const country = document.body.dataset.country;
    setStatus(`geo.status.${['UA', 'RU', 'KZ', 'BY'].includes(country) ? country : 'DEFAULT'}`);
    if (country === 'UA') setTabletUkraine(true);
    prepareStatusButton();
  });

  window.ChillGeo = {
    refresh: () => refresh({ force: true, ignoreOverride: true }),
    applyTestCountry(country) {
      const normalized = String(country || '').toUpperCase();
      if (normalized === 'AUTO') { testCountry = null; return refresh({ force: true, ignoreOverride: true }); }
      if (normalized === 'DEFAULT') { testCountry = 'DEFAULT'; applyCountry(null, { test: true }); return Promise.resolve(null); }
      if (/^[A-Z]{2}$/.test(normalized)) { testCountry = normalized; applyCountry(normalized, { forceLocale: true, test: true }); return Promise.resolve(normalized); }
      return Promise.reject(new Error('Invalid country code'));
    }
  };
})();
